using FlexExtractor;
using Microsoft.Win32.SafeHandles;
using System.Diagnostics;
using System.Runtime.InteropServices;
static partial class Cases {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFileW(string path,uint access,uint share,IntPtr security,uint mode,uint flags,IntPtr template);
 public static void TestReviewSoakSharingViolationInjectionRecovers(){Directory.CreateDirectory(TestRoot);var before=Directory.GetDirectories(TestRoot,"soak-*").ToHashSet(StringComparer.OrdinalIgnoreCase);using var process=Process.Start(new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"FlexExtractor.Tests.exe")){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,ArgumentList={"--soak","26"}})!;var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();try{var clock=Stopwatch.StartNew();string? watch=null;while(clock.Elapsed.TotalSeconds<8){watch=Directory.GetDirectories(TestRoot,"soak-*").Where(p=>!before.Contains(p)).Select(p=>Path.Combine(p,"watch")).FirstOrDefault(Directory.Exists);if(watch!=null)break;Thread.Sleep(20);}Program.Check(watch!=null,"soak fixture did not start");using(var handle=CreateFileW(watch!,0x80000000,3,IntPtr.Zero,3,0x02000000,IntPtr.Zero)){Program.Check(!handle.IsInvalid,"directory sharing fixture open failed "+Marshal.GetLastWin32Error());Thread.Sleep(17500);}Program.Check(process.WaitForExit(25000),"soak injection retry unbounded");var text=output.GetAwaiter().GetResult()+error.GetAwaiter().GetResult();Console.WriteLine(text);Program.Check(process.ExitCode==0,"soak failed under transient directory sharing violation");Program.Check(text.Contains("SOAK RECOVERED")&&text.Contains("SOAK RESULT"),"soak did not verify post-outage new-file recovery");}finally{if(!process.HasExited){process.Kill(true);process.WaitForExit(5000);}}}
}
